	@Test
	public void hashJoinKeepsJaggedSubqueryUndefRowCompatibleWithOuterBinding() {
		String query = "SELECT ?x ?y WHERE { VALUES ?x { <urn:outer> } "
				+ "{ SELECT ?x ?y WHERE { VALUES (?x ?y) { (UNDEF 1) } } LIMIT 1 } }";
		ParsedQuery parsed = QueryParserUtil.parseQuery(QueryLanguage.SPARQL, query, null);
		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(new EmptyTripleSource(), null);

		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(parsed.getTupleExpr())
				.evaluate(EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}

		assertEquals(1, rows.size(), "an UNDEF subquery binding is compatible with the outer ?x mapping");
		assertEquals(SimpleValueFactory.getInstance().createIRI("urn:outer"), rows.get(0).getValue("x"));
		assertEquals(SimpleValueFactory.getInstance().createLiteral(BigInteger.ONE), rows.get(0).getValue("y"));
	}

	private static List<BindingSet> evaluateExpressionErrorRightOperand(boolean optional) {
		SimpleValueFactory vf = SimpleValueFactory.getInstance();
		BindingSetAssignment left = new BindingSetAssignment();
		QueryBindingSet leftRow = new QueryBindingSet();
		leftRow.addBinding("left", vf.createLiteral(1));
		left.setBindingSets(List.of(leftRow));

		MathExpr divisionByZero = new MathExpr(new ValueConstant(vf.createLiteral(1)),
				new ValueConstant(vf.createLiteral(0)), MathExpr.MathOp.DIVIDE);
		Extension right = new Extension(new SingletonSet(),
				new ExtensionElem(divisionByZero, "error"),
				new ExtensionElem(new FunctionCall("STRUUID"), "fresh"));
		QueryRoot query = new QueryRoot(optional ? new LeftJoin(left, right) : new Join(left, right));

		StrictEvaluationStrategy strategy = new StrictEvaluationStrategy(new EmptyTripleSource(), null);
		List<BindingSet> rows = new ArrayList<>();
		try (CloseableIteration<BindingSet> iteration = strategy.precompile(query)
				.evaluate(EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}
		return rows;
	}

